package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.DateTimeFieldType;
import org.joda.time.base.AbstractPartial;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Partial_withField_TriageGen0Test {

    @Test
    public void testWithField_SameValue_ReturnsThis() {
        DateTimeFieldType fieldType = DateTimeFieldType.yearOfPeriod();
        int value = 2023;
        Partial partial = new Partial(new DateTimeFieldType[]{fieldType}, new int[]{value});

        Partial result = partial.withField(fieldType, value);

        // If value is same, it should return the same instance (identity check)
        Assert.assertSame("Should return the same instance when value is unchanged", partial, result);
    }

    @Test
    public void testWithField_DifferentValue_ReturnsNewPartial() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfPeriod();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType[] types = {yearType, monthType};
        int[] values = {2023, 1};

        Partial partial = new Partial(types, values);
        int newValue = 2024;

        Partial result = partial.withField(yearType, newValue);

        // Should be a new instance
        Assert.assertNotSame("Should return a new instance when value is changed", partial, result);
        Assert.assertEquals("New year should be 2024", newValue, result.getValue(0));
        Assert.assertEquals("Month should remain 1", 1, result.getValue(1));
        Assert.assertEquals("Size should remain the same", partial.size(), result.size());
    }

    @Test
    public void testWithField_MultipleFields_UpdatesCorrectIndex() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfPeriod();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonthOfPeriod();
        DateTimeFieldType[] types = {yearType, monthType, dayType};
        int[] values = {2023, 5, 15};

        Partial partial = new Partial(types, values);
        int newValue = 20;

        // Update the day (index 2)
        Partial result = partial.withField(dayType, newValue);

        Assert.assertEquals("Year should remain 2023", 2023, result.getValue(0));
        Assert.assertEquals("Month should remain 5", 5, result.getValue(1));
        Assert.assertEquals("Day should be updated to 20", 20, result.getValue(2));
    }

    @Test
    public void testWithField_WithChronology() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfPeriod();
        int[] values = {2023};
        DateTimeFieldType[] types = {yearType};

        // Using ISOChronology explicitly
        Partial partial = new Partial(types, values, ISOChronology.getInstanceUTC());

        Partial result = partial.withField(yearType, 2025);

        Assert.assertEquals("Year should be updated", 2025, result.getValue(0));
        Assert.assertSame("Chronology should be retained", partial.getChronology(), result.getChronology());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWithField_UnsupportedField_ThrowsException() {
        // Create a partial with only Year
        DateTimeFieldType yearType = DateTimeFieldType.yearOfPeriod();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2023});

        // Try to set Month which is not in the partial's field types
        // indexOfSupported should throw exception if field is not supported
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        partial.withField(monthType, 12);
    }
}
